import{_ as s,o as n,c as t,a2 as a}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"OCIRE - OpenCubeOS Independent Recovery Environment","description":"","frontmatter":{},"headers":[],"relativePath":"dev/ocire.md","filePath":"dev/ocire.md"}'),o={name:"dev/ocire.md"};function i(r,e,c,l,d,p){return n(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="ocire-opencubeos-independent-recovery-environment" tabindex="-1">OCIRE - OpenCubeOS Independent Recovery Environment <a class="header-anchor" href="#ocire-opencubeos-independent-recovery-environment" aria-label="Permalink to &quot;OCIRE - OpenCubeOS Independent Recovery Environment&quot;">​</a></h1><p>Status: <strong>3.0.0-WP-01-ocire-core</strong> (this work package lands the core: OCIRE boots independently and runs a minimal shell).</p><h2 id="what-ocire-is" tabindex="-1">What OCIRE is <a class="header-anchor" href="#what-ocire-is" aria-label="Permalink to &quot;What OCIRE is&quot;">​</a></h2><p>OCIRE is a second L0 kernel, fully independent of the Open Cube OS (OCOS) kernel. It lives in its own source tree (<code>ocire/</code>), shares no headers with OCOS, links with its own linker script (<code>ocire/linker_ocire.ld</code>) and produces its own boot image (<code>build/ocire/ocire.iso</code>). The two-kernel architecture:</p><ul><li><strong>L0 = provides services</strong> — OCOS stays the full-service kernel. OCIRE is an L0 <em>peer</em>: a recovery kernel that boots when OCOS cannot.</li><li><strong>Independent</strong> — OCIRE must be able to boot, run and power-cycle the machine without any OCOS code, data or partition being reachable or required.</li></ul><h2 id="what-wp-01-ships" tabindex="-1">What WP-01 ships <a class="header-anchor" href="#what-wp-01-ships" aria-label="Permalink to &quot;What WP-01 ships&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>WP-01 (this)</th><th>WP-02</th><th>WP-03</th></tr></thead><tbody><tr><td>Boot + minimal shell</td><td><strong>here</strong></td><td>—</td><td>—</td></tr><tr><td>help / shutdown / reboot</td><td><strong>here</strong></td><td>—</td><td>—</td></tr><tr><td>Recovery features, FAT12, self-check, repair</td><td>—</td><td>here</td><td>—</td></tr><tr><td>Boot-failure detection, 1-minute timeout</td><td>—</td><td>here</td><td>—</td></tr><tr><td>OCOS &lt;-&gt; OCIRE interface, process protection</td><td>—</td><td>—</td><td>here</td></tr></tbody></table><p>The shell command set is exactly three commands (<code>help</code>, <code>shutdown</code>, <code>reboot</code>) — fixed for this work package, nothing more.</p><h2 id="source-layout-ocire" tabindex="-1">Source layout (ocire/) <a class="header-anchor" href="#source-layout-ocire" aria-label="Permalink to &quot;Source layout (ocire/)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ocire/</span></span>
<span class="line"><span>  ocire_mb2_header.S    multiboot2 header (80x25 text mode request)</span></span>
<span class="line"><span>  ocire_boot.S          32-bit GRUB entry -&gt; GDT + 4 GiB identity map</span></span>
<span class="line"><span>                        -&gt; long mode -&gt; ocire_main; exception stubs</span></span>
<span class="line"><span>  ocire_main.c          kernel entry: console, IDT, ACPI, shell</span></span>
<span class="line"><span>  ocire_console.c/.h    dual console: COM1 115200 + VGA text 0xB8000</span></span>
<span class="line"><span>  ocire_input.c/.h      serial + PS/2 polled input (shift/caps/backsp)</span></span>
<span class="line"><span>  ocire_idt.c/.h        minimal IDT: 32 exception vectors, faults</span></span>
<span class="line"><span>                        print a diagnostic instead of triple-faulting</span></span>
<span class="line"><span>  ocire_acpi.c/.h       RSDP/XSDT/FADT (checksums verified), tiny \\_S5</span></span>
<span class="line"><span>                        package reader, PM1a S5 + RESET_REG + 8042</span></span>
<span class="line"><span>  ocire_shell.c/.h      the three commands, honest unknown-command hint</span></span>
<span class="line"><span>  ocire_util.c/.h       freestanding mem/string helpers</span></span>
<span class="line"><span>  ocire_io.h            port I/O inline helpers</span></span>
<span class="line"><span>  ocire_types.h         base scalar types</span></span>
<span class="line"><span>  ocire.mk              build targets (included from the top Makefile)</span></span>
<span class="line"><span>  linker_ocire.ld       own link layout (1 MiB load address)</span></span>
<span class="line"><span>  grub-ocire.cfg        standalone ISO menu (single entry)</span></span>
<span class="line"><span>  grub-dual.cfg         dual-boot disk menu (OCOS default, OCIRE entry)</span></span></code></pre></div><p>Build targets: <code>make ocire-kernel</code>, <code>make ocire-iso</code>, <code>make ocire-disk</code>, <code>make ocire-test</code>, <code>make ocire-dual-test</code> (run targets <code>ocire-run-bios/uefi[-gui]</code> are also available). Compilation uses the same <code>-Wall -Wextra -Werror</code> zero-warning gate as the OCOS kernel; CI runs the OCIRE build on every push.</p><h2 id="how-the-two-oses-coexist-wp-01-layout" tabindex="-1">How the two OSes coexist (WP-01 layout) <a class="header-anchor" href="#how-the-two-oses-coexist-wp-01-layout" aria-label="Permalink to &quot;How the two OSes coexist (WP-01 layout)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hd0 (ocire-boot.img, built by tools/make_ocire_disk.sh)</span></span>
<span class="line"><span>  MBR + GRUB (BIOS: boot.img + core.img in the post-MBR gap;</span></span>
<span class="line"><span>              UEFI: /EFI/BOOT/BOOTX64.EFI on the FAT32 partition)</span></span>
<span class="line"><span>  p1 FAT32: /boot/opencube.elf (OCOS kernel)</span></span>
<span class="line"><span>            /boot/ocire.elf    (copy of the OCIRE kernel)</span></span>
<span class="line"><span>            /boot/grub/grub.cfg (the dual menu)</span></span>
<span class="line"><span>  -&gt; GRUB menu entry 1 boots OCOS (default)</span></span>
<span class="line"><span>  -&gt; GRUB menu entry 2 boots OCIRE</span></span>
<span class="line"><span></span></span>
<span class="line"><span>hd1 (ocire-hd.img) - the OCIRE disk</span></span>
<span class="line"><span>  MBR with ONE entry, type 0xEE (&quot;GPT protective shadow&quot;), no GPT</span></span>
<span class="line"><span>  header behind it; the raw OCIRE kernel image is stored at the</span></span>
<span class="line"><span>  partition start (LBA 2048).</span></span>
<span class="line"><span>  -&gt; the GRUB menu loads it with a whole-disk blocklist:</span></span>
<span class="line"><span>     multiboot2 (hd1)2048+128</span></span>
<span class="line"><span>  -&gt; OCOS refuses the entire partition table (0xEE makes its parser</span></span>
<span class="line"><span>     switch to GPT mode, which fails without a GPT header), so the</span></span>
<span class="line"><span>     OCIRE partition has no device node and no filesystem path in</span></span>
<span class="line"><span>     OCOS - see &quot;Partition isolation&quot; below.</span></span></code></pre></div><p>Two lessons from bring-up, encoded here for the record:</p><ol><li>GRUB 2.12&#39;s msdos partmap <strong>skips</strong> 0xEE entries — a partition path like <code>(hd1,msdos1)</code> does not exist for GRUB even though the same entry is perfectly valid on disk. The menu therefore uses a whole-disk blocklist.</li><li>GRUB menus have no digit hotkeys; automation selects entries with the ANSI cursor-down sequence over the serial menu terminal.</li></ol><h2 id="partition-isolation-the-wp-01-acceptance-test" tabindex="-1">Partition isolation (the WP-01 acceptance test) <a class="header-anchor" href="#partition-isolation-the-wp-01-acceptance-test" aria-label="Permalink to &quot;Partition isolation (the WP-01 acceptance test)&quot;">​</a></h2><p>Measured in <code>evidence/3_0_0_wp01_ocire/isolation.log</code> from inside a running OCOS with both disks attached:</p><ul><li><code>partscan: 1 partition device(s) registered</code> — the OCIRE disk contributes <strong>zero</strong> child devices (only the dual-boot disk&#39;s p1 registers).</li><li><code>parted hda</code> (OCIRE disk) → <code>no partition table found</code>.</li><li><code>mkfs.fat32 hdap1 confirm</code> → <code>device not found</code> — there is no node to write through.</li><li><code>disk_rw_test hdap1</code> → <code>device lookup FAIL</code> — there is no node to read through.</li><li><code>df</code> — only OCOS volumes are mounted; nothing from the OCIRE disk.</li></ul><p>Honest boundary (also measured, <code>isolation_rawdecl.log</code>): whole-disk device nodes still exist — <code>disk_rw_test hda</code> and <code>mkfs.fat32 hda confirm</code> both work on a throwaway copy, exactly like Linux root with <code>/dev/sdb</code>. Blocking administrator-level whole-disk operations requires an OCOS block-layer policy — an OCOS kernel change this work package explicitly forbids — and belongs to WP-03 (process protection).</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li><code>tools/run_ocire_tests.py</code> (<code>make ocire-test</code>) — 14 cases, BIOS + UEFI: boot to the shell prompt, <code>help</code>, unknown-command hint, backspace editing, <code>shutdown</code> (ACPI S5; QEMU really exits) and <code>reboot</code> (8042/RESET_REG; with <code>-no-reboot</code> QEMU really exits).</li><li><code>tools/run_ocire_dual_tests.py</code> (<code>make ocire-dual-test</code>) — 11 cases: the four dual-boot combinations (BIOS/UEFI x menu default OCOS / menu-pick OCIRE), the five isolation probes and the two whole-disk declaration probes.</li><li>Full OCOS regression matrix on a tree that contains OCIRE but zero OCOS edits: <code>evidence/3_0_0_wp01_ocire/regression/</code> (host tests, reproducible-check, wp12, wp10_tui, chinese, tuiqa x2, native x2, l1_per_app, wait4 fresh-boot battery 20/20, boot gates) — all green and identical to the 2.2.0 release baseline.</li></ul>`,21)])])}const m=s(o,[["render",i]]);export{u as __pageData,m as default};
